import{_ as a,o,c as t,ag as d}from"./chunks/framework.DyxC4IQh.js";const u=JSON.parse('{"title":"常见问题","description":"按键没反应、标签看着不对、跟输入法或其他改键应用撞上这类问题。","frontmatter":{"description":"按键没反应、标签看着不对、跟输入法或其他改键应用撞上这类问题。"},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1792208533000}'),i={name:"guide/faq.md"};function c(r,e,l,h,p,n){return o(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="按-f-打不出字母-f-了" tabindex="-1">按 F 打不出字母 f 了 <a class="header-anchor" href="#按-f-打不出字母-f-了" aria-label="Permalink to &quot;按 F 打不出字母 f 了&quot;">​</a></h2><p>hint 模式内 <code>F</code> 是退出键，会吃掉。要连续打 <code>f</code> 的场景（写代码、聊天）不该在 hint 模式里：按 <code>Esc</code> 出来。</p><p>输入法弹出的时候不用担心这件事，VimAct 那时把按键完全交回 IME，<code>f</code> 正常上屏。</p><h2 id="装了、开了服务、按-f-没反应" tabindex="-1">装了、开了服务、按 F 没反应 <a class="header-anchor" href="#装了、开了服务、按-f-没反应" aria-label="Permalink to &quot;装了、开了服务、按 F 没反应&quot;">​</a></h2><p>按这个顺序排查：</p><ol><li>VimAct 主界面状态行是不是 <code>Status: enabled</code>。</li><li>当前 App 有没有被加进<a href="/vimact-site/guide/settings.html">排除列表</a>。</li><li>输入法是不是正弹着。</li><li>ROM 的省电策略有没有把应用冻结，见<a href="/vimact-site/guide/accessibility.html">各家 ROM 的额外坑</a>。</li></ol><p>四条都排除了还没反应，属于 OEM 的 <code>onKeyEvent</code> 兼容性问题。这是 v0.1 明确的风险项，把机型和 ROM 版本记下来。</p><h2 id="有些控件没有标签" tabindex="-1">有些控件没有标签 <a class="header-anchor" href="#有些控件没有标签" aria-label="Permalink to &quot;有些控件没有标签&quot;">​</a></h2><p>自绘控件拿不到标签：游戏画面、<code>SurfaceView</code>、部分图表，开发者没把它们暴露成无障碍节点，谁都看不见。</p><p>目标太多也会被截。一次扫描最多收 400 个目标；能贴出多少标签另算，封顶是当前字符集的平方，默认字符集 16 个字母、最多 256 个标签，多出来的目标拿不到标签。</p><p>WebView 里的网页按浏览器暴露给无障碍树的结构处理，长页面或自定义滚动容器会打折。</p><h2 id="标签亮了-按下没反应" tabindex="-1">标签亮了，按下没反应 <a class="header-anchor" href="#标签亮了-按下没反应" aria-label="Permalink to &quot;标签亮了，按下没反应&quot;">​</a></h2><p>节点只支持长按。<code>isClickable()</code> 为 false、动作里只有 <code>ACTION_LONG_CLICK</code> 的元素照样会被采集、照样贴上标签，但发出去的是短按，长按才有的动作做不出来：长按弹菜单、长按进多选、长按拖起一个图标。目前没有长按通道，这一类元素标上了也点不动，见<a href="/vimact-site/guide/hints.html">Hint 标签点击</a>。</p><p>兜底那一下打偏了。<code>ACTION_CLICK</code> 拿不到结果时改打坐标，落点取节点边界框的中心。多数控件的热区就是它自己，中心不会有事；热区只占一角、边界框却很大的元素（自绘卡片、整块图区）可能打偏，这种时候用手指点原来的位置仍然有效。</p><h2 id="标签为什么突然整套变了" tabindex="-1">标签为什么突然整套变了 <a class="header-anchor" href="#标签为什么突然整套变了" aria-label="Permalink to &quot;标签为什么突然整套变了&quot;">​</a></h2><p>为了保持「没有任何标签是另一个标签的前缀」，重排有时候比局部修补更省事，此时整套重新分配一次。表现是滚动一下屏幕，所有标签集体变一次。</p><h2 id="长列表怎么往下滚" tabindex="-1">长列表怎么往下滚 <a class="header-anchor" href="#长列表怎么往下滚" aria-label="Permalink to &quot;长列表怎么往下滚&quot;">​</a></h2><p>光标模式（没进 hint 模式）下随便滚：VimAct 只吃方向键、点击键、通知键和触发键，<code>PageUp</code>/<code>PageDown</code>、方向箭头这些照旧交给前台应用，列表该怎么动还怎么动。滚完按方向键，光标会重新吸附到最近的候选上。</p><p>hint 模式里滚不动。这是模态，所有按键都被吃掉，<code>PageDown</code> 也不例外：它不写进输入缓冲，却也传不到前台应用。要往下就按 <code>Esc</code> 退出、滚一页、再按 <code>F</code> 重来，重扫时标签按节点身份保留，原来标 <code>b</code> 的大概率还是 <code>b</code>。</p><h2 id="和-key-mapper-会不会打架" tabindex="-1">和 Key Mapper 会不会打架 <a class="header-anchor" href="#和-key-mapper-会不会打架" aria-label="Permalink to &quot;和 Key Mapper 会不会打架&quot;">​</a></h2><p>非 hint 模式下 VimAct 只接手自己那几个键：方向键、光标点击键、通知键和触发键，其余一律放行。这求的是共存，不是集成。</p><p>需要留意的是键位撞车：如果 Key Mapper 也把 <code>F</code> 或 <code>Space</code> 映射了别的动作，两边都会想拦。建议把 VimAct 的通知键或光标点击键（见设置）挪开，或者在 Key Mapper 侧避开这几个键。</p><h2 id="会不会读到我的密码" tabindex="-1">会不会读到我的密码 <a class="header-anchor" href="#会不会读到我的密码" aria-label="Permalink to &quot;会不会读到我的密码&quot;">​</a></h2><p>无障碍服务能读到的东西由系统决定：节点类名、<code>viewId</code>、文本、<code>contentDescription</code>、边界坐标。它拿不到屏幕像素，那需要录屏权限，VimAct 没申请。</p><p>密码类输入框在系统层默认不会把明文文本回传给无障碍节点。而且输入框一旦激活、输入法弹出，VimAct 立刻收起全部标签和光标，完全不碰按键。</p><p>至于读取范围本身：APK 没有 <code>INTERNET</code> 权限，装机的权限清单上可以直接看到。数据没有出口。</p><h2 id="费电吗" tabindex="-1">费电吗 <a class="header-anchor" href="#费电吗" aria-label="Permalink to &quot;费电吗&quot;">​</a></h2><p>那个 32 毫秒的重扫循环只在两种情况下跑：hint 模式开着，或者光标还活着。空闲时它一次也不执行，只等系统事件。通知角标走另一条路：SystemUI 发事件才去查通知行，两次查询间隔不少于 16 毫秒，角标出现和消失各用 140 毫秒淡入淡出。</p><h2 id="需要-root-或者跑-adb-命令吗" tabindex="-1">需要 root 或者跑 ADB 命令吗 <a class="header-anchor" href="#需要-root-或者跑-adb-命令吗" aria-label="Permalink to &quot;需要 root 或者跑 ADB 命令吗&quot;">​</a></h2><p>都不需要。第一次设置只有安装 APK 和打开无障碍服务开关两步。网上有些同类工具的教程要求你常驻 <code>adb shell</code> 或执行 <code>input tap</code>，VimAct 走的是 <code>dispatchGesture</code>，那条路不需要 shell。</p><h2 id="分屏、画中画、折叠屏外屏" tabindex="-1">分屏、画中画、折叠屏外屏 <a class="header-anchor" href="#分屏、画中画、折叠屏外屏" aria-label="Permalink to &quot;分屏、画中画、折叠屏外屏&quot;">​</a></h2><p>折叠屏和平板的物理键盘场景是主要目标之一，常规使用没问题。分屏、多窗口、画中画下只依赖活动窗口的根节点，行为不做保证。</p><h2 id="源码在哪能看到" tabindex="-1">源码在哪能看到 <a class="header-anchor" href="#源码在哪能看到" aria-label="Permalink to &quot;源码在哪能看到&quot;">​</a></h2><p>目前不开源，页面上也没有 GitHub 按钮。首个正式版发布时一并说明源码计划。</p>',35)])])}const f=a(i,[["render",c]]);export{u as __pageData,f as default};
